"""黄金快照 fixtures：账单样本生成（脱敏；幂等，重复运行覆盖为相同内容）。

来源与口径：
- meituan.csv      真机样本（2026-10-13）脱敏：用户名/订单号/卡号打码，商户与金额保留；
- alipay_*.csv     合成（GBK，按 import_bill 注释记载的导出结构），含退款/交易关闭/0 元行、
                   无备注列变体（验 note_fallback_last）；
- wechat.xlsx      合成（openpyxl 生成），前言 18 行、已全额退款红包原消费行（方向守卫）、
                   信用卡还款（transfer_types）、-退款 后缀行、交易关闭行（row_filter）；
- jd.csv           合成（utf-8-sig），三种括号形态、空格多分类、含尾 \\t 单元格、独立退款行；
- export_new/old.csv 本应用导出两代列名（新：支付账户/收款账户/流水ID/退款关联；旧：合并列），
                   新版含退款对（two_pass 批内直连）与归属列。

用法：python tests/fixtures/make_fixtures.py
"""
import io
import pathlib

ROOT = pathlib.Path(__file__).resolve().parent
BILLS = ROOT / "bills"


def _w(name: str, text: str, enc: str = "utf-8-sig") -> None:
    BILLS.mkdir(parents=True, exist_ok=True)
    (BILLS / name).write_bytes(text.encode(enc))


