def main() -> None:
    _w("meituan.csv", MEITUAN)
    _w("alipay_gbk.csv", ALIPAY, enc="gbk")
    _w("alipay_noremark_gbk.csv", ALIPAY_NOREMARK, enc="gbk")
    _w("jd.csv", JD)
    _w("export_new.csv", EXPORT_NEW, enc="utf-8")
    _w("export_old.csv", EXPORT_OLD, enc="utf-8")
    from openpyxl import Workbook
    wb = Workbook()
    ws = wb.active
    for row in WECHAT_ROWS:
        ws.append(row)
    buf = io.BytesIO()
    wb.save(buf)
    (BILLS / "wechat.xlsx").write_bytes(buf.getvalue())
    print(f"fixtures written to {BILLS} ({len(list(BILLS.iterdir()))} files)")


if __name__ == "__main__":
    main()
